        StringReader reader = new StringReader("<node>test</node>");

        builder.initialiseParse(reader, "http://base.uri", Parser.xmlParser());
        assertEquals("http://base.uri", builder.baseUri());
    }

    @Test(expected = IllegalArgumentException.class)
